{"cards": [{"node_code": "N_b8b733d0ec4733a0", "definition": "研究数控机床及自动化设备的底层控制核心，包括G代码解析、轨迹插补算法、伺服驱动控制及多轴联动运动规划技术。", "boundary": "聚焦于设备内部的实时运动控制逻辑与算法实现，确保刀具或执行器按预定轨迹精确运动。边界在于关注控制原理、算法精度及实时性，不涉及上层工艺路径规划（归入CAM节点）或机器人本体结构（归入机器人节点）。", "includes": ["数控系统插补算法（直线、圆弧、样条等）及误差补偿", "伺服驱动系统、电机控制及多轴同步运动规划", "G代码/M代码解析、后处理及运动学正逆解计算"], "excludes": ["基于CAD模型的刀具路径生成策略（归入CAM节点）", "机器人本体的机械结构设计或传感器硬件选型"], "sibling_distinctions": [{"other_code": "N_a4d2cc375aa1e932", "rule": "本节点关注控制算法与运动执行（如何动），兄弟节点关注工艺路径生成与数据转换（动哪里）。"}, {"other_code": "N_fab5a9c8b855894e", "rule": "本节点关注通用运动控制原理，兄弟节点关注特定机器人本体的集成与产线布局。"}], "cross_boundary_rule": "若研究侧重轨迹生成的工艺逻辑，主挂载CAM节点；若侧重轨迹执行的插补精度与实时控制，主挂载本节点。"}, {"node_code": "N_fab5a9c8b855894e", "definition": "研究工业机器人在制造场景中的应用，包括机器人本体集成、自动生产线布局、物料搬运及多设备协同制造单元构建。", "boundary": "聚焦于机器人作为执行单元在生产线中的集成与协同，涵盖机器人选型、编程、工作站设计及产线物流自动化。边界在于关注系统集成与产线级自动化，不涉及机器人内部运动控制算法（归入运动控制）或纯机械结构设计。", "includes": ["工业机器人编程、轨迹规划及与机床/AGV的协同控制", "自动生产线布局、物料搬运系统（AS/RS）及物流自动化", "机器人工作站设计、安全防护及多机器人协作系统"], "excludes": ["机器人本体机械结构、减速器或伺服电机的研发（归入机械设计与基础零部件）", "纯软件层面的MES系统架构或数据模型设计"], "sibling_distinctions": [{"other_code": "N_b8b733d0ec4733a0", "rule": "本节点关注机器人系统集成与产线应用，兄弟节点关注底层运动控制算法与插补原理。"}, {"other_code": "N_24037d69307c0750", "rule": "本节点侧重具体设备（机器人）的集成，兄弟节点侧重系统架构的柔性与重构能力。"}], "cross_boundary_rule": "若研究侧重机器人本体硬件或控制算法，主挂载相应基础节点；若侧重机器人与产线其他设备的集成与协同，主挂载本节点。"}, {"node_code": "N_24037d69307c0750", "definition": "研究由数控设备、机器人及自动化物流系统组成的柔性制造单元（FMC）与柔性制造系统（FMS）的架构、调度与重构技术。", "boundary": "聚焦于制造系统的柔性化设计，包括系统架构、资源调度、动态重构及多品种小批量生产模式下的系统优化。边界在于关注系统层面的柔性与调度策略，不涉及具体设备控制（归入运动控制）或纯管理流程（归入生产系统规划）。", "includes": ["柔性制造单元（FMC）与柔性制造系统（FMS）的架构设计", "制造资源动态调度、任务分配及系统重构策略", "多品种小批量生产模式下的系统柔性与适应性优化"], "excludes": ["单一设备的数控编程或运动控制算法（归入运动控制节点）", "不涉及具体制造设备集成的纯管理信息系统设计"], "sibling_distinctions": [{"other_code": "N_fab5a9c8b855894e", "rule": "本节点关注系统架构与调度策略，兄弟节点关注具体机器人/设备的集成与布局。"}, {"other_code": "N_b8b733d0ec4733a0", "rule": "本节点关注系统级柔性与调度，兄弟节点关注设备级运动控制与插补。"}], "cross_boundary_rule": "若研究侧重具体设备集成，主挂载机器人/设备节点；若侧重系统架构、调度算法及柔性重构，主挂载本节点。"}]}
